// 5 ---------------------------------------------------------------
d.h1('5 Требования к видам обеспечения');
d.h2('5.1 Математическое и алгоритмическое обеспечение');
d.p('Итоговая стоимость заявки рассчитывается по формуле:');
d.p('S = Σ Ц(р)ᵢ + Σ Ц(з)ⱼ × Kⱼ,', { align: AlignmentType.CENTER, noIndent: true, run: { italics: true } });
d.p('где Ц(р)ᵢ — стоимость i-й работы из журнала работ; Ц(з)ⱼ — цена j-й запчасти на момент резервирования; Kⱼ — количество j-й запчасти (без учёта отменённых резервов). Для гарантийной заявки S = 0.', { noIndent: true });
d.list([
  'остаток к оплате: S − Σ оплат по заявке; выдача разрешена при остатке, равном нулю;',
  'доступный остаток запчасти: на складе − в резерве; резерв создаётся, если доступный остаток не меньше запрошенного количества;',
  'расхождение инвентаризации: Δ = факт − учёт; при Δ ≠ 0 учётный остаток корректируется, операция записывается в журнал движения;',
  'признак просрочки: плановый срок < текущей даты и статус не является конечным;',
  'проверка смены статуса выполняется по таблице допустимых переходов (конечный автомат) с учётом роли пользователя;',
  'блокировка входа: после 5 неудачных попыток подряд вход запрещается на 15 минут, счётчик сбрасывается после успешного входа.',
]);
